CREATE TABLE public.teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.teams TO authenticated; GRANT ALL ON public.teams TO service_role; ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.team_members (team_id uuid NOT NULL REFERENCES public.teams(id), user_id uuid NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','member')), PRIMARY KEY(team_id,user_id));
GRANT SELECT ON public.team_members TO authenticated; GRANT ALL ON public.team_members TO service_role; ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES public.teams(id), name text NOT NULL);
GRANT SELECT ON public.workspaces TO authenticated; GRANT ALL ON public.workspaces TO service_role; ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.team_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES public.teams(id), token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), created_by uuid NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');
GRANT SELECT ON public.team_invites TO authenticated; GRANT ALL ON public.team_invites TO service_role; ALTER TABLE public.team_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rooms ADD COLUMN workspace_id uuid REFERENCES public.workspaces(id);
CREATE FUNCTION public.team_has_access(p_team uuid,p_owner boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.team_members WHERE team_id=p_team AND user_id=auth.uid() AND (NOT p_owner OR role='owner')) $$;
REVOKE ALL ON FUNCTION public.team_has_access(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.team_has_access(uuid,boolean) TO authenticated;
CREATE POLICY team_read ON public.teams FOR SELECT TO authenticated USING(public.team_has_access(id));
CREATE POLICY member_read ON public.team_members FOR SELECT TO authenticated USING(public.team_has_access(team_id));
CREATE POLICY workspace_read ON public.workspaces FOR SELECT TO authenticated USING(public.team_has_access(team_id));
CREATE POLICY invite_read ON public.team_invites FOR SELECT TO authenticated USING(public.team_has_access(team_id,true));
CREATE FUNCTION public.team_create(p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF auth.uid() IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'Sign in and enter a team name'; END IF; INSERT INTO public.teams(name,created_by) VALUES(trim(p_name),auth.uid()) RETURNING id INTO t; INSERT INTO public.team_members VALUES(t,auth.uid(),'owner'); INSERT INTO public.workspaces(team_id,name) VALUES(t,'Shared studio'); RETURN t; END $$;
CREATE FUNCTION public.team_invite_create(p_team uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF NOT public.team_has_access(p_team,true) THEN RAISE EXCEPTION 'Only owners can invite'; END IF; INSERT INTO public.team_invites(team_id,created_by) VALUES(p_team,auth.uid()) RETURNING token INTO t; RETURN t; END $$;
CREATE FUNCTION public.team_invite_accept(p_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT team_id INTO t FROM public.team_invites WHERE token=p_token AND expires_at>now(); IF t IS NULL THEN RAISE EXCEPTION 'Invitation expired or unavailable'; END IF; INSERT INTO public.team_members(team_id,user_id) VALUES(t,auth.uid()) ON CONFLICT DO NOTHING; RETURN t; END $$;
CREATE FUNCTION public.team_member_remove(p_team uuid,p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.team_has_access(p_team,true) THEN RAISE EXCEPTION 'Only owners can remove members'; END IF; DELETE FROM public.team_members WHERE team_id=p_team AND user_id=p_user AND role='member'; END $$;
CREATE FUNCTION public.workspace_attach_room(p_workspace uuid,p_room uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=p_workspace AND public.team_has_access(team_id)) THEN RAISE EXCEPTION 'Workspace access required'; END IF; UPDATE public.rooms SET workspace_id=p_workspace WHERE id=p_room AND host_id=auth.uid() AND (workspace_id IS NULL OR workspace_id=p_workspace); IF NOT FOUND THEN RAISE EXCEPTION 'Only the signed-in meeting host can attach this room'; END IF; END $$;
CREATE FUNCTION public.workspace_rooms() RETURNS SETOF public.rooms LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.* FROM public.rooms r JOIN public.workspaces w ON w.id=r.workspace_id WHERE public.team_has_access(w.team_id) ORDER BY r.created_at DESC LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.team_create(text), public.team_invite_create(uuid), public.team_invite_accept(uuid), public.team_member_remove(uuid,uuid), public.workspace_attach_room(uuid,uuid), public.workspace_rooms() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.team_create(text), public.team_invite_create(uuid), public.team_invite_accept(uuid), public.team_member_remove(uuid,uuid), public.workspace_attach_room(uuid,uuid), public.workspace_rooms() TO authenticated;